[
  {
    "text": "In logic applications, the use of self-aligned double patterning (SADP) with high-NA EUV can eliminate at-resolution stitching by decomposing critical layers into non-stitching sub-layers, as demonstrated by design-technology co-optimization studies.",
    "topic": "SADP and high-NA EUV co-optimization"
  },
  {
    "text": "Central obscuration illumination in high-NA EUV improves the depth of focus for DRAM storage node contacts sufficiently to allow single-exposure full-field printing without stitching at 0.33 NA-equivalent resolutions below 30 nm pitch.",
    "topic": "DOF improvement for DRAM contacts"
  },
  {
    "text": "At-resolution stitching can be avoided by restricting stitch boundaries to non-critical areas (e.g., between memory sub-arrays) where CD uniformity requirements are relaxed by a factor of 2 or more.",
    "topic": "Stitch boundary placement strategy"
  },
  {
    "text": "Curvilinear mask patterns designed with inverse lithography technology (ILT) for high-NA EUV can extend the single-exposure resolution to cover larger logic blocks, eliminating the need for at-resolution stitching on metal and via layers.",
    "topic": "ILT resolution enhancment for stitching reduction"
  }
]
